insert into categories (id, name, emoji, description, sort_order) values ('playful', 'Playful & Silly', '🎈', 'Harmless teasing — safe for almost anyone', 0);
insert into categories (id, name, emoji, description, sort_order) values ('public', 'Safe in Public', '😌', 'Mild enough for the office and grandma', 1);
insert into categories (id, name, emoji, description, sort_order) values ('banter', 'Best-Friend Banter', '🤝', 'For people who will laugh, not sue', 2);
insert into categories (id, name, emoji, description, sort_order) values ('frustration', 'Everyday Frustration', '🤦', 'Traffic, stubbed toes, Mondays', 3);
insert into categories (id, name, emoji, description, sort_order) values ('nuclear', 'Full Send', '💥', 'Explicit. Know them — think twice before throwing them', 4);
insert into languages (code, name, native_name, flag, status, note) values ('en', 'English', 'English', '🇬🇧', 'full', null);
insert into variants (code, language_code, name, flag) values ('en-GB', 'en', 'British', '🇬🇧');
insert into variants (code, language_code, name, flag) values ('en-US', 'en', 'American', '🇺🇸');
