insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-01', 'en', 'idiot', 'ID-ee-ut', 'idiot', 'idiot', 'The universal baseline. Works in every English-speaking country.', 'public', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-02', 'en', 'moron', 'MOR-on', 'moron', 'moron', 'One notch above idiot on the frustration scale.', 'frustration', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-03', 'en', 'dipstick', 'DIP-stick', 'fool', 'oil-measuring rod', 'Charmingly retro; peak usage in 1980s sitcoms.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-04', 'en', 'airhead', 'AIR-hed', 'scatterbrain', 'head full of air', 'For friends who forget why they walked into the room.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-05', 'en', 'bonehead', 'BOHN-hed', 'blockhead', 'head of bone', 'Implies solid skull, no interior. Sports-commentary favourite.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-06', 'en', 'numbskull', 'NUM-skul', 'dimwit', 'numb skull', 'Old-timey enough to be safe almost anywhere.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-07', 'en', 'clown', 'klown', 'clown', 'clown', 'Modern internet-speak for someone whose decisions are a circus.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-08', 'en', 'couch potato', 'KOWCH po-TAY-to', 'lazy person', 'potato on a couch', 'Coined in 1976; the potato has never moved since.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-09', 'en', 'loser', 'LOO-zer', 'loser', 'one who loses', 'Stings more in America, where winning is a lifestyle.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-10', 'en', 'tool', 'tool', 'obnoxious fool', 'tool', 'Someone used by others and too dim to notice.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-11', 'en', 'smartass', 'SMART-ass', 'smart aleck', 'clever arse', 'Spelled ''smart-arse'' in the UK and Australia, naturally.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-12', 'en', 'jerk', 'jurk', 'jerk', 'sudden pull', 'America''s everyday word for a selfish person.', 'frustration', 1);
insert into entry_variants (entry_id, variant_code) values ('en-12', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-13', 'en', 'dumbass', 'DUM-ass', 'dumbass', 'dumb arse', 'American classic; affection level depends entirely on tone.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('en-13', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-14', 'en', 'jackass', 'JAK-ass', 'jackass', 'male donkey', 'Technically just a donkey. Tell that to the person you called it.', 'frustration', 2);
insert into entry_variants (entry_id, variant_code) values ('en-14', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-15', 'en', 'douchebag', 'DOOSH-bag', 'obnoxious jerk', 'hygiene device', 'Distinctly American; describes a very specific gym-mirror personality.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('en-15', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-16', 'en', 'schmuck', 'shmuk', 'fool / jerk', 'Yiddish: penis', 'New York via Yiddish. Ruder in origin than it sounds today.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('en-16', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-17', 'en', 'putz', 'puts', 'fool', 'Yiddish: penis', 'Schmuck''s gentler cousin. Also a verb: to putz around.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('en-17', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-18', 'en', 'dingus', 'DING-us', 'goofball', 'thingamajig', 'So harmless it loops back around to being funny.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('en-18', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-19', 'en', 'doofus', 'DOO-fus', 'goof', 'doofus', 'The gold standard for affectionate American teasing.', 'playful', 1);
