insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-20', 'en', 'knucklehead', 'NUK-el-hed', 'blockhead', 'head of knuckles', 'What American dads call sons who deserve better insults.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('en-20', 'en-US');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-21', 'en', 'son of a bitch', 'sun uv uh BICH', 'son of a bitch', 'son of a female dog', 'Doubles as an exclamation when you stub your toe.', 'nuclear', 3);
