insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-22', 'en', 'motherfucker', 'MUH-ther-fuk-er', 'motherfucker', '(self-explanatory)', 'Maximum American firepower. Handle like fireworks.', 'nuclear', 3);
