insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-24', 'en', 'arsehole', 'ARSS-hohl', 'arsehole', 'anus', 'Same weapon, British calibre. The ''r'' adds gravitas.', 'nuclear', 3);
