insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-28', 'en', 'pillock', 'PIL-uk', 'fool', '16th-c. word for penis', 'Sounds quaint now; your nan can say it in church.', 'playful', 1);
