insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-29', 'en', 'plonker', 'PLONK-er', 'fool', 'something that plonks', 'Immortalised by Only Fools and Horses: ''You plonker, Rodney.''', 'playful', 1);
