insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-30', 'en', 'muppet', 'MUP-pet', 'fool', 'the puppet', 'Being called a felt puppet is somehow deeply humbling.', 'banter', 1);
