insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-31', 'en', 'numpty', 'NUMP-tee', 'silly fool', 'numpty', 'Scotland''s finest export after whisky. Almost affectionate.', 'playful', 1);
