insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-32', 'en', 'git', 'git', 'unpleasant person', 'misbegotten one', 'Short, sharp, very British. ''Miserable old git'' is the full package.', 'banter', 2);
