insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-33', 'en', 'knobhead', 'NOB-hed', 'dickhead', 'knob head', 'Northern England''s contribution to world culture.', 'banter', 2);
