insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-35', 'en', 'twat', 'twat', 'twat', 'vulgar: vulva', 'Deceptively strong in Britain — do not confuse with twit.', 'nuclear', 3);
