insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-36', 'en', 'bugger', 'BUG-er', 'damn / rascal', 'sodomite (archaic)', 'Now mostly an exclamation: ''Oh bugger.'' Very versatile.', 'frustration', 2);
