insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-37', 'en', 'sod off', 'SOD off', 'get lost', 'sod = turf/archaic sodomite', 'The polite end of Britain''s go-away spectrum.', 'frustration', 2);
