insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-42', 'en', 'drongo', 'DRONG-go', 'fool', 'named after a racehorse', 'Drongo the horse ran 37 races in the 1920s and won none. Legend.', 'playful', 1);
