insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-43', 'en', 'galah', 'guh-LAH', 'loud fool', 'a pink cockatoo', 'Named after Australia''s noisiest, silliest bird. ''Flamin'' galah!''', 'playful', 1);
