insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-44', 'en', 'dag', 'dag', 'dork (affectionate)', 'matted wool on a sheep''s rear', 'Somehow a compliment in Australia. A loveable dag is a national ideal.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('en-44', 'en-AU');
