insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-48', 'en', 'prick', 'prik', 'prick', 'sharp point / vulgar: penis', 'Universally understood, universally rude.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-49', 'en', 'dickhead', 'DIK-hed', 'dickhead', 'penis head', 'The international standard unit of male obnoxiousness.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('en-50', 'en', 'blockhead', 'BLOK-hed', 'blockhead', 'head like a block of wood', 'Old enough that Charlie Brown got called it for 50 years.', 'playful', 1);
insert into languages (code, name, native_name, flag, status, note) values ('fr', 'French', 'Français', '🇫🇷', 'full', null);
insert into variants (code, language_code, name, flag) values ('fr-FR', 'fr', 'France', '🇫🇷');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-01', 'fr', 'zut', 'zuut', 'darn', 'darn', 'The mildest French curse; what teachers say when they drop chalk.', 'public', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-02', 'fr', 'mince', 'manss', 'shoot', 'thin', 'Polite stand-in for ''merde'', like saying ''sugar'' instead of… you know.', 'public', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-03', 'fr', 'andouille', 'ahn-DOO-yuh', 'dummy', 'tripe sausage', 'Being called a sausage is a French rite of passage.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-04', 'fr', 'cornichon', 'kor-nee-SHOHN', 'dope', 'little pickle', 'France insults you with charcuterie-board items. Respect it.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-05', 'fr', 'patate', 'pah-TAHT', 'silly', 'potato', 'Affectionate. ''Grosse patate'' between friends is basically love.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-06', 'fr', 'banane', 'bah-NAHN', 'goof', 'banana', 'Yes, the fruit-based insult family is large in France.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-07', 'fr', 'nouille', 'NOO-yuh', 'noodle / dimwit', 'noodle', 'Soft, floppy, no spine. The metaphor writes itself.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-08', 'fr', 'cruche', 'kruush', 'airhead', 'jug', 'Empty vessel, makes noise when tapped.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-09', 'fr', 'gourde', 'goord', 'dimwit', 'flask / gourd', 'Like cruche but with outdoor-shop energy.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-10', 'fr', 'truffe', 'truuf', 'dolt', 'truffle', 'The most expensive fungus becomes the cheapest insult.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-11', 'fr', 'quiche', 'keesh', 'klutz', 'quiche', 'Modern slang: ''être une quiche en maths'' = to be hopeless at maths.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-12', 'fr', 'boulet', 'boo-LEH', 'dead weight', 'cannonball (on a chain)', 'The friend the group drags around like a prisoner''s iron ball.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-13', 'fr', 'râleur', 'rah-LUHR', 'whiner', 'groaner', 'Complaining is a national sport; a râleur is its professional athlete.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-14', 'fr', 'mytho', 'mee-TOH', 'liar', 'short for mythomaniac', 'Teen slang for someone whose stories deserve a Netflix deal.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-15', 'fr', 'guignol', 'geen-YOL', 'clown', 'the puppet Guignol', 'From the famous Lyon puppet theatre. ''Arrête ton guignol'' = stop clowning.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-16', 'fr', 'bouffon', 'boo-FOHN', 'clown / fool', 'court jester', 'Revived by banlieue slang; delivery matters more than the word.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-17', 'fr', 'blaireau', 'bleh-ROH', 'loser', 'badger', 'Why the badger? Nobody knows. The badger did nothing wrong.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-18', 'fr', 'ringard', 'ran-GAR', 'uncool / has-been', 'fire poker', 'Deadly in Paris, where being outdated is worse than being rude.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-19', 'fr', 'radin', 'rah-DAN', 'cheapskate', 'stingy one', 'For the friend who ''forgot their wallet'' four dinners in a row.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-20', 'fr', 'flemmard', 'fleh-MAR', 'lazybones', 'one full of ''flemme''', '''J''ai la flemme'' (can''t be bothered) is a complete French sentence and lifestyle.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-21', 'fr', 'tête de mule', 'tet duh MUUL', 'stubborn as a mule', 'mule head', 'Standard-issue for family arguments.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-22', 'fr', 'casse-pieds', 'kass-PYEH', 'pain in the neck', 'foot-breaker', 'The polite version of a much less polite expression below.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-23', 'fr', 'gros nul', 'groh NUUL', 'big loser', 'big zero', 'Schoolyard classic; scales from playground to office.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-24', 'fr', 'espèce d''idiot', 'es-PESS dee-DYOH', 'you idiot', 'species of idiot', '''Espèce de…'' upgrades any insult by making it taxonomic.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-25', 'fr', 'pauvre type', 'pohv TEEP', 'sad sack', 'poor guy', 'Pity as a weapon. Devastating with a slow head-shake.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-26', 'fr', 'minable', 'mee-NAHBL', 'pathetic', 'shabby', 'Cold, dismissive, very effective in a Parisian accent.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-27', 'fr', 'tocard', 'toh-KAR', 'loser', 'bad racehorse', 'Horse-racing slang for a nag that never wins.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-28', 'fr', 'plouc', 'plook', 'hick', 'from Breton place names (Plou-)', 'Parisian snobbery distilled into one syllable. Use with irony only.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-29', 'fr', 'crétin', 'kreh-TAN', 'cretin', 'cretin', 'Stronger in French than English; a favourite of Captain Haddock.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-30', 'fr', 'imbécile', 'am-beh-SEEL', 'imbecile', 'imbecile', 'Classic, slightly literary. Molière-approved.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-31', 'fr', 'abruti', 'ah-bruu-TEE', 'moron', 'made brutish', 'The go-to for describing other drivers.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-32', 'fr', 'débile', 'deh-BEEL', 'moronic', 'feeble', '''C''est débile'' (that''s idiotic) is said about 400 times per French day.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-33', 'fr', 'merde', 'maird', 'shit', 'shit', 'Also means ''break a leg'' to actors. France contains multitudes.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-34', 'fr', 'bordel', 'bor-DEL', 'damn it / mess', 'brothel', '''Quel bordel!'' = what a mess. Combines beautifully with other words.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-35', 'fr', 'fait chier', 'feh shee-EH', 'so annoying', 'makes (one) shit', '''Ça me fait chier'' is the national anthem of Monday mornings.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-36', 'fr', 'putain', 'puu-TAN', 'damn / fuck', 'whore', 'In the south it''s punctuation. Can express joy, rage, awe, and cheese appreciation.', 'frustration', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-37', 'fr', 'con', 'kohn', 'idiot', 'vulgar: vulva', 'So overused it barely registers — ''le petit con'' is almost tender.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-38', 'fr', 'connard', 'koh-NAR', 'asshole', 'con + pejorative suffix', 'Con''s aggressive big brother. Standard traffic vocabulary.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-39', 'fr', 'connasse', 'koh-NASS', 'asshole (feminine)', 'feminine of connard', 'Grammatically feminine, equally rude.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-40', 'fr', 'salaud', 'sah-LOH', 'bastard', 'dirty one', 'Sartre wrote philosophy about ''les salauds''. Still rude at dinner.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-41', 'fr', 'salopard', 'sah-loh-PAR', 'scumbag', 'dirty one + suffix', 'Salaud with extra gravel in the voice.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-42', 'fr', 'enfoiré', 'ahn-fwah-REH', 'asshole', 'soiled one', 'Paradox: also the affectionate name of a beloved charity concert group.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-43', 'fr', 'ducon', 'duu-KOHN', 'dumbass', 'of-the-con', 'Turns ''con'' into a fake aristocratic surname. Monsieur Ducon.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-44', 'fr', 'trou du cul', 'troo duu KUU', 'asshole', 'hole of the arse', 'Anatomically identical to the English version. Global consensus.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-45', 'fr', 'tête de nœud', 'tet duh NUH', 'dickhead', 'knot head', 'Sounds like sailing vocabulary. Is not sailing vocabulary.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-46', 'fr', 'casse-couilles', 'kass-KOO-yuh', 'pain in the ass', 'ball-breaker', 'The rude big sibling of casse-pieds.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-47', 'fr', 'emmerdeur', 'ahn-mair-DUHR', 'pain in the ass', 'one who covers you in shit', 'An entire French film (L''Emmerdeur, 1973) honours this person.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-48', 'fr', 'ta gueule', 'tah GUHL', 'shut up', 'your (animal) mouth', 'Using ''gueule'' (an animal''s maw) for a human face is the insult inside the insult.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-49', 'fr', 'va te faire foutre', 'vah tuh fair FOOTR', 'go fuck yourself', 'go get yourself done', 'The end of the escalation ladder. There is nothing after this.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('fr-50', 'fr', 'n''importe quoi', 'nan-port KWAH', 'utter nonsense', 'no matter what', 'Said with an eye-roll, it dismisses entire worldviews. Peak French.', 'public', 1);
insert into languages (code, name, native_name, flag, status, note) values ('de', 'German', 'Deutsch', '🇩🇪', 'full', null);
insert into variants (code, language_code, name, flag) values ('de-DE', 'de', 'Standard German', '🇩🇪');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-01', 'de', 'Mist', 'mist', 'crap / darn', 'manure', 'Completely socially acceptable — German grandmas say it hourly.', 'public', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-02', 'de', 'Verdammt', 'fair-DAMT', 'damn it', 'damned', 'The standard reaction to a missed train, i.e. said rarely — German trains are never late (joke).', 'public', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-03', 'de', 'Blödsinn', 'BLERD-zin', 'nonsense / rubbish', 'stupid sense', 'Perfect for dismissing an argument without swearing.', 'public', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-04', 'de', 'Depp', 'dep', 'fool', 'fool', 'In Bavaria almost a term of endearment.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-05', 'de', 'Trottel', 'TROT-tel', 'dimwit', 'dawdler', 'Classic Austrian favourite; mild and slightly affectionate.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-06', 'de', 'Dummkopf', 'DOOM-kopf', 'blockhead', 'dumb head', 'The one German insult every cartoon villain taught the world.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-07', 'de', 'Schwachkopf', 'SHVAKH-kopf', 'numbskull', 'weak head', 'A slightly fancier Dummkopf.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-08', 'de', 'Spinner', 'SHPIN-ner', 'nutcase', 'spinner', 'From ''spinnen'' — to spin yarn, i.e. to talk crazy. ''Du spinnst!'' = you''re nuts!', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-09', 'de', 'Weichei', 'VYKH-eye', 'wimp', 'soft egg', 'Part of a whole family of wimp-insults Germans invent for fun.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-10', 'de', 'Warmduscher', 'VARM-doo-sher', 'softie', 'warm-showerer', 'Someone too soft to shower cold. Peak German compound-word comedy.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-11', 'de', 'Schattenparker', 'SHAT-ten-par-ker', 'wimp', 'shadow-parker', 'A man who parks in the shade so the car stays cool. Devastating.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-12', 'de', 'Lappen', 'LAP-pen', 'loser / wet rag', 'rag', 'Youth slang; also what you lose when caught speeding (the licence).', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-13', 'de', 'Pfeife', 'PFY-fuh', 'useless person', 'whistle', 'Someone who just blows air. Popular with football coaches.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-14', 'de', 'Flasche', 'FLA-shuh', 'failure', 'bottle', 'Empty on the inside. ''Flasche leer!'' became legendary via coach Trapattoni''s meltdown.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-15', 'de', 'Niete', 'NEE-tuh', 'dud', 'losing lottery ticket', 'A person who never wins anything, including arguments.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-16', 'de', 'Angsthase', 'ANGST-hah-zuh', 'scaredy-cat', 'fear-rabbit', 'Kind enough for kindergarten, pointed enough for your hiking buddy.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-17', 'de', 'Faulpelz', 'FOWL-pelts', 'lazybones', 'lazy pelt', 'For the flatmate whose dishes have achieved sentience.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-18', 'de', 'Schnarchnase', 'SHNARKH-nah-zuh', 'slowpoke', 'snore-nose', 'For people who are asleep even while awake.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-19', 'de', 'Klugscheißer', 'KLOOG-shy-ser', 'smart-ass', 'smart-shitter', 'The person who corrects your grammar mid-argument.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-20', 'de', 'Korinthenkacker', 'ko-RIN-ten-KAK-ker', 'nitpicker', 'currant-crapper', 'Someone whose pedantry produces output as tiny as currants.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-21', 'de', 'Erbsenzähler', 'AIRB-zen-tsay-ler', 'bean counter', 'pea-counter', 'The accountant of joy. Counts peas, kills vibes.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-22', 'de', 'Sesselpupser', 'ZES-sel-POOP-ser', 'desk jockey', 'armchair-farter', 'Office worker who has never lifted anything heavier than a stapler.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-23', 'de', 'Suppenkasper', 'ZOOP-pen-KAS-per', 'picky eater', 'soup-Kasper', 'From the 1845 children''s book Struwwelpeter — the boy who refused his soup.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-24', 'de', 'Quatschkopf', 'KVATCH-kopf', 'silly-billy', 'nonsense-head', 'Affectionate; safe to use on children and CEOs alike.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-25', 'de', 'Labertasche', 'LAH-ber-TA-shuh', 'chatterbox', 'blabber-bag', 'For the friend whose voice memos are 11 minutes long.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-26', 'de', 'Hosenscheißer', 'HOH-zen-SHY-ser', 'chicken / coward', 'pants-shitter', 'Vulgar but mostly used teasingly among friends.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-27', 'de', 'Halbdackel', 'HALP-dak-kel', 'half-wit', 'half a dachshund', 'Swabian speciality: a full Dackel (dachshund) is already an insult — this is half of one.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-28', 'de', 'Honk', 'honk', 'dork', '(nonsense word)', 'Youth slang, allegedly from ''Hauptschüler ohne nennenswerte Kenntnisse''.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-29', 'de', 'Pappnase', 'PAP-nah-zuh', 'clown', 'cardboard nose', 'The red carnival nose — calling someone one means they''re a joke.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-30', 'de', 'Knalltüte', 'KNAL-tuu-tuh', 'nutjob', 'banging bag', 'A party popper of a person: loud, sudden, no content.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-31', 'de', 'Dumpfbacke', 'DOOMPF-bak-kuh', 'airhead', 'dull cheek', 'Popularised by the German dub of ''Married... with Children''.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-32', 'de', 'Lauch', 'lowkh', 'weakling', 'leek', 'Gym-culture slang: thin, pale, bends easily.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-33', 'de', 'Rotzlöffel', 'ROTS-lerf-fel', 'cheeky brat', 'snot-spoon', 'Reserved for other people''s children.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-34', 'de', 'Jammerlappen', 'YAM-mer-LAP-pen', 'whiner', 'whining rag', 'For people who complain about the weather. So, everyone.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-35', 'de', 'Miesepeter', 'MEE-zuh-PAY-ter', 'sourpuss', 'grumpy Peter', 'Poor Peter. Nobody knows what he did to deserve this.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-36', 'de', 'Stinkstiefel', 'SHTINK-shtee-fel', 'grump', 'stinky boot', 'Radiates bad mood the way an old boot radiates smell.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-37', 'de', 'Schwachmat', 'SHVAKH-maht', 'dimwit', 'weak-mate', 'Colloquial blend of ''schwach'' (weak) and ''Schachmatt'' (checkmate).', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-38', 'de', 'Scheiße', 'SHY-suh', 'shit', 'shit', 'Statistically Germany''s most-used word after ''ja''. Fits every situation.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-39', 'de', 'Blödmann', 'BLERD-man', 'dummy', 'stupid man', 'Mild classic; the German equivalent of calling someone a doofus.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-40', 'de', 'Vollidiot', 'FOL-ee-dee-OHT', 'total idiot', 'full idiot', 'The ''Voll-'' prefix upgrades any insult to premium.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-41', 'de', 'Vollpfosten', 'FOL-pfos-ten', 'complete moron', 'full fence post', 'As smart and useful as a wooden post. Standard traffic commentary.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-42', 'de', 'Arschgeige', 'ARSH-guy-guh', 'jerk', 'arse-violin', 'Nobody knows what an arse-violin is, which makes it perfect.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-43', 'de', 'Arschkriecher', 'ARSH-kree-kher', 'kiss-ass', 'arse-crawler', 'For colleagues whose agreement with the boss is load-bearing.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-44', 'de', 'Mistkerl', 'MIST-kairl', 'scumbag', 'manure guy', 'Old-fashioned but heartfelt; what your Oma calls TV villains.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-45', 'de', 'Drecksack', 'DREK-zak', 'dirtbag', 'sack of dirt', 'Serious insult — the friendship discount does not apply.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-46', 'de', 'Kotzbrocken', 'KOTS-bro-ken', 'obnoxious jerk', 'chunk of vomit', 'Reserved for people who are exhausting on a molecular level.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-47', 'de', 'Arschloch', 'ARSH-lokh', 'asshole', 'arse-hole', 'The heavyweight champion. Also a popular German card game, confusingly.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-48', 'de', 'Verpiss dich', 'fair-PISS dikh', 'piss off', 'piss yourself away', 'Ends conversations. Occasionally friendships.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-49', 'de', 'Leck mich am Arsch', 'LEK mikh am ARSH', 'kiss my ass', 'lick me on the arse', 'Literary pedigree: Goethe put it in a play in 1773. National treasure.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('de-50', 'de', 'Hurensohn', 'HOO-ren-zohn', 'son of a bitch', 'son of a whore', 'Extremely strong — fight-starter territory. Know it, don''t throw it.', 'nuclear', 3);
insert into languages (code, name, native_name, flag, status, note) values ('es', 'Spanish', 'Español', '🇪🇸', 'full', null);
insert into variants (code, language_code, name, flag) values ('es-ES', 'es', 'Spain', '🇪🇸');
insert into variants (code, language_code, name, flag) values ('es-419', 'es', 'Latin America', '🇲🇽');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-01', 'es', 'tonto', 'TON-toh', 'silly', 'silly', 'The baseline. ''Tonto del pueblo'' = the village fool.', 'public', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-02', 'es', 'bobo', 'BOH-boh', 'silly / goofy', 'silly', 'Even softer than tonto. Grandmother-approved.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-03', 'es', 'payaso', 'pah-YAH-soh', 'clown', 'clown', 'Football fans'' favourite word for referees across two continents.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-04', 'es', 'ganso', 'GAHN-soh', 'goofball', 'goose', '''Hacer el ganso'' = to clown around.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-05', 'es', 'pavo', 'PAH-voh', 'dork', 'turkey', 'Also teen slang for awkward: ''la edad del pavo'' = the awkward age.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('es-05', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-06', 'es', 'melón', 'meh-LOHN', 'melonhead', 'melon', 'Big, round, hollow. Spain loves produce-based insults.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('es-06', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-07', 'es', 'besugo', 'beh-SOO-goh', 'dimwit', 'sea bream', 'A fish famous for its blank stare. ''Diálogo de besugos'' = a dialogue of the deaf.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('es-07', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-08', 'es', 'papanatas', 'pah-pah-NAH-tahs', 'simpleton', 'cream-eater', 'Old-school and delightful to pronounce.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('es-08', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-09', 'es', 'mequetrefe', 'meh-keh-TREH-feh', 'good-for-nothing', 'meddler', 'Sounds like a spell from Harry Potter; means ''useless busybody''.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-10', 'es', 'zoquete', 'soh-KEH-teh', 'blockhead', 'block of wood', 'Literally a chunk of wood. The Spanish Dummkopf.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-11', 'es', 'zopenco', 'soh-PEN-koh', 'dunce', 'dunce', 'Rarely heard from anyone under 60, which makes it funnier.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-12', 'es', 'memo', 'MEH-moh', 'dimwit', 'simpleton', 'Short and punchy; very Madrid.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('es-12', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-13', 'es', 'lerdo', 'LAIR-doh', 'slowpoke', 'slow / clumsy', 'For people who process life on dial-up.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-14', 'es', 'idiota', 'ee-DYOH-tah', 'idiot', 'idiot', 'International vocabulary; works from Madrid to Buenos Aires.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-15', 'es', 'imbécil', 'eem-BEH-seel', 'imbecile', 'imbecile', 'A notch angrier than idiota.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-16', 'es', 'estúpido', 'es-TOO-pee-doh', 'stupid', 'stupid', 'Feels harsher in Spanish than English — use with intent.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-17', 'es', 'tarado', 'tah-RAH-doh', 'idiot', 'defective', 'Everyday word in Latin America, especially Argentina.', 'frustration', 2);
insert into entry_variants (entry_id, variant_code) values ('es-17', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-18', 'es', 'pesado', 'peh-SAH-doh', 'annoying / clingy', 'heavy', 'The person whose texts arrive in stacks of nine.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-19', 'es', 'plasta', 'PLAHS-tah', 'bore', 'sticky blob', 'Spain''s word for someone who sticks to you at parties.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('es-19', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-20', 'es', 'rata', 'RAH-tah', 'cheapskate', 'rat', 'Universal; the friend who splits a coffee three ways.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-21', 'es', 'vago', 'BAH-goh', 'slacker', 'wanderer / idle', 'The default parental accusation across the Spanish-speaking world.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-22', 'es', 'flojo', 'FLOH-khoh', 'lazy', 'loose / slack', 'Latin American counterpart of vago.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('es-22', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-23', 'es', 'sinvergüenza', 'seen-vair-GWEN-sah', 'shameless rascal', 'without shame', 'Somehow both an insult and a compliment, depending on the aunt saying it.', 'banter', 1);
