insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-27', 'es', 'aguafiestas', 'ah-gwah-FYES-tahs', 'party pooper', 'party-waterer', 'The person who mentions Monday on a Saturday night.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-28', 'es', 'cantamañanas', 'kahn-tah-mah-NYAH-nahs', 'unreliable blowhard', 'morning-singer', 'Announces grand plans at dawn; delivers nothing by dusk.', 'playful', 1);
