insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-29', 'es', 'cazurro', 'kah-SOO-roh', 'pigheaded', 'sullen / stubborn', 'Rural Spain''s finest word for a mule in human form.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('es-29', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-30', 'es', 'gilipollas', 'khee-lee-POH-yahs', 'asshole / jerk', 'gilí (foolish) + pollas', 'THE Spanish insult. Spain runs on coffee, olive oil, and this word.', 'nuclear', 3);
