insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-31', 'es', 'capullo', 'kah-POO-yoh', 'jerk', 'cocoon / flower bud', 'Botanically innocent, socially devastating.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('es-31', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-32', 'es', 'tonto del culo', 'TON-toh del KOO-loh', 'complete idiot', 'silly of the arse', 'Anatomically upgraded tonto. Very Spain.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('es-32', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-33', 'es', 'joder', 'khoh-DAIR', 'damn / fuck', 'to fuck', 'Spain''s all-purpose exclamation; conjugated less often than exclaimed.', 'frustration', 3);
insert into entry_variants (entry_id, variant_code) values ('es-33', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-34', 'es', 'coño', 'KOH-nyoh', 'damn', 'vulgar: vulva', 'In Spain it''s punctuation; in parts of Latin America it''s a real slap.', 'frustration', 3);
insert into entry_variants (entry_id, variant_code) values ('es-34', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-35', 'es', 'hostia', 'OS-tyah', 'damn / whoa', 'communion wafer', 'Blasphemy-powered. ''Hostia puta'' is Spain''s turbo mode.', 'frustration', 2);
insert into entry_variants (entry_id, variant_code) values ('es-35', 'es-ES');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-36', 'es', 'mamón', 'mah-MOHN', 'jerk / suck-up', 'suckler', 'In Spain a jerk; in Mexico a pretentious one. Either way, unflattering.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-37', 'es', 'cabrón', 'kah-BROHN', 'bastard', 'big male goat', 'In Mexico, ''qué cabrón'' between friends can be pure admiration. Context is everything.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-38', 'es', 'pinche', 'PEEN-cheh', 'damn / lousy', 'kitchen assistant', 'Mexico''s favourite adjective. ''Pinche tráfico'' = damn traffic.', 'frustration', 2);
insert into entry_variants (entry_id, variant_code) values ('es-38', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-39', 'es', 'pendejo', 'pen-DEH-khoh', 'dumbass', 'pubic hair', 'Mexico''s crown jewel. Harmless in Peru, moderate in Cuba — geography matters.', 'nuclear', 3);
insert into entry_variants (entry_id, variant_code) values ('es-39', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-40', 'es', 'güey', 'way', 'dude / idiot', 'from buey (ox)', 'Mexican Swiss Army knife: greeting, insult, and comma all at once.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('es-40', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-41', 'es', 'chingado', 'cheen-GAH-doh', 'damn / screwed', 'from chingar (to screw)', 'The chingar verb family has ~50 meanings in Mexico. A national linguistics project.', 'frustration', 3);
insert into entry_variants (entry_id, variant_code) values ('es-41', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-42', 'es', 'boludo', 'boh-LOO-doh', 'dude / fool', 'big-balled', 'Argentina''s national word. ''Che, boludo'' is how friendships breathe.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('es-42', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-43', 'es', 'pelotudo', 'peh-loh-TOO-doh', 'idiot', 'big-balled (stronger)', 'Boludo''s angry older brother. Not affectionate.', 'nuclear', 3);
insert into entry_variants (entry_id, variant_code) values ('es-43', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-44', 'es', 'forro', 'FOH-roh', 'jerk', 'lining / slang: condom', 'Buenos Aires special. Do not translate literally in a pharmacy.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('es-44', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-45', 'es', 'gil', 'kheel', 'sucker', 'naive fool', 'Tango lyrics are full of gils. Lunfardo slang classic.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('es-45', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-46', 'es', 'huevón', 'weh-VOHN', 'dude / lazybones', 'big-egged', 'In Chile it''s every third word (''weón''); meaning shifts with tone.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('es-46', 'es-419');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-47', 'es', 'hijo de puta', 'EE-khoh deh POO-tah', 'son of a bitch', 'son of a whore', 'Heavyweight everywhere. In Spain, weirdly, sometimes admiring (''el muy hijo de puta ganó'').', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-48', 'es', 'vete a la mierda', 'VEH-teh ah lah MYAIR-dah', 'go to hell', 'go to the shit', 'Direct, geographic, effective.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-49', 'es', 'no me jodas', 'noh meh KHOH-dahs', 'you''re kidding me', 'don''t fuck me', 'Mostly means ''no way!'' — outrage and disbelief in one package.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('es-50', 'es', 'qué cabrón eres', 'keh kah-BROHN EH-res', 'you sneaky devil', 'what a big goat you are', 'Said with a grin, it''s a trophy. Said flat, it''s a problem.', 'banter', 2);
insert into languages (code, name, native_name, flag, status, note) values ('af', 'Afrikaans', 'Afrikaans', '🇿🇦', 'starter', null);
insert into variants (code, language_code, name, flag) values ('af-ZA', 'af', 'South Africa', '🇿🇦');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-01', 'af', 'domkop', 'DOM-kop', 'blockhead', 'dumb head', 'Direct descendant of the German Dummkopf, with a South African tan.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-02', 'af', 'pampoen', 'pam-POON', 'fool', 'pumpkin', 'The Afrikaans produce aisle strikes: big, round, hollow.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-03', 'af', 'moegoe', 'MOO-khoo', 'fool / bumpkin', 'fool', 'Township slang absorbed into general Afrikaans; gentle mockery.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-04', 'af', 'skelm', 'SKEL-um', 'rascal / sneak', 'rogue', 'Can be affectionate (''you little skelm!'') or a genuine accusation of shadiness.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-05', 'af', 'papbroek', 'PAP-brook', 'coward', 'porridge-pants', 'Trousers full of maize porridge: zero structural integrity, like your courage.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-06', 'af', 'luigat', 'LAY-khut', 'lazybones', 'lazy hole', 'For the friend whose weekend plans are horizontal.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-07', 'af', 'windgat', 'VINT-khut', 'show-off', 'wind hole', 'Someone powered entirely by their own hot air.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-08', 'af', 'bliksem', 'BLIK-sem', 'rascal / damn', 'lightning', 'Noun, verb, and exclamation: ''Ek sal jou bliksem'' = I''ll wallop you. Weather as a weapon.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-09', 'af', 'jou gat', 'yoh KHUT', 'no way / your foot', 'your backside', 'The standard scoff at nonsense claims. Braai-side essential.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('af-10', 'af', 'gaan bars', 'khan BARS', 'get lost', 'go burst', 'You are instructed to explode, elsewhere. Vivid and final.', 'frustration', 2);
insert into languages (code, name, native_name, flag, status, note) values ('ar', 'Arabic', 'العربية', '🇪🇬', 'starter', 'There is no single spoken Arabic. The most useful varieties for learners: Egyptian (most widely understood thanks to film and TV), Levantine (Syria, Lebanon, Jordan, Palestine), then Gulf and Maghrebi. Nobody insults anyone in Modern Standard Arabic.');
insert into variants (code, language_code, name, flag) values ('ar-EG', 'ar', 'Egyptian', '🇪🇬');
insert into variants (code, language_code, name, flag) values ('ar-LEV', 'ar', 'Levantine', '🇱🇧');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-01', 'ar', 'يا غبي', 'ya ghabi (yah GHA-bee)', 'you idiot', 'O stupid one', 'The ''ya'' vocative starts most Arabic insults — you announce your target formally.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-02', 'ar', 'يا أهبل', 'ya ahbal (yah AH-bal)', 'you fool', 'O simpleton', 'Everyday and mostly harmless between friends.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-03', 'ar', 'يا بليد', 'ya balid (yah bah-LEED)', 'you dimwit', 'O dull one', 'For slow replies in the group chat.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-04', 'ar', 'يا حمار', 'ya humar (yah hoo-MAR)', 'you donkey', 'O donkey', 'The classic across the whole Arab world. The donkey carries civilisation and its insults.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-05', 'ar', 'يا فاشل', 'ya fashil (yah FAA-shil)', 'you failure', 'O failing one', 'Stings precisely because parents use it. Deploy carefully.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-06', 'ar', 'يا زفت', 'ya zift (yah ZIFT)', 'you''re awful', 'O tar/asphalt', 'Egyptian: anything bad is ''zift'' — the weather, the traffic, your cousin.', 'frustration', 1);
insert into entry_variants (entry_id, variant_code) values ('ar-06', 'ar-EG');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-07', 'ar', 'روح بلّط البحر', 'ruh ballat il-bahr (roo bal-LAT el-BAHR)', 'get lost', 'go tile the sea', 'Egyptian masterpiece: go do something impossible, far away from me.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('ar-07', 'ar-EG');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-08', 'ar', 'خرا', 'khara (KHA-rah)', 'shit', 'excrement', 'Pan-Arab frustration fuel. ''Yom khara'' = a shit day.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-09', 'ar', 'يا كلب', 'ya kalb (yah KELB)', 'you dog', 'O dog', 'Much heavier in Arabic than English — dogs rank low in traditional insult hierarchy. Fight-adjacent.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ar-10', 'ar', 'كل خرا', 'kol khara (kol KHA-rah)', 'eat shit', 'eat excrement', 'Levantine favourite for ending negotiations permanently.', 'nuclear', 3);
insert into entry_variants (entry_id, variant_code) values ('ar-10', 'ar-LEV');
insert into languages (code, name, native_name, flag, status, note) values ('zh', 'Chinese', '中文', '🇨🇳', 'starter', null);
insert into variants (code, language_code, name, flag) values ('zh-CN', 'zh', 'Mandarin', '🇨🇳');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-01', 'zh', '笨蛋', 'bèn dàn (bun-dahn)', 'idiot', 'stupid egg', 'Chinese insults love eggs. This is the mild, even affectionate one.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-02', 'zh', '傻瓜', 'shǎ guā (shah-gwah)', 'silly', 'silly melon', 'So soft that couples use it as a pet name.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-03', 'zh', '白痴', 'bái chī (by-chih)', 'idiot', 'white fool', 'Noticeably harsher than bèndàn; not for flirting.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-04', 'zh', '二百五', 'èr bǎi wǔ (ar-by-woo)', 'fool', 'two hundred fifty', 'From ancient coin strings: 500 made a unit, so 250 is half-strung — half-finished.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-05', 'zh', '蠢货', 'chǔn huò (chwun-hwoh)', 'moron', 'stupid goods', 'Being called defective merchandise: efficient and cutting.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-06', 'zh', '废物', 'fèi wù (fay-woo)', 'useless person', 'waste material', 'Strong in family arguments; gamers throw it around constantly.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-07', 'zh', '混蛋', 'hún dàn (hwun-dahn)', 'bastard / jerk', 'mixed egg', 'The egg escalation continues. Implies muddled, disreputable origins.', 'nuclear', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-08', 'zh', '王八蛋', 'wáng bā dàn (wong-bah-dahn)', 'bastard', 'turtle egg', 'Peak egg. Turtles were linked to infidelity in old folklore — deep insult archaeology.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-09', 'zh', '滚开', 'gǔn kāi (gwun-kai)', 'get lost', 'roll away', 'Vivid: you''re told to physically roll out of sight. 滚 alone works too.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('zh-10', 'zh', '吃货', 'chī huò (chih-hwoh)', 'glutton / foodie', 'eating goods', 'Once an insult, now a badge of honour on food blogs. Language evolves.', 'playful', 1);
insert into languages (code, name, native_name, flag, status, note) values ('nl', 'Dutch', 'Nederlands', '🇳🇱', 'starter', null);
insert into variants (code, language_code, name, flag) values ('nl-NL', 'nl', 'Netherlands', '🇳🇱');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-01', 'nl', 'sukkel', 'SUK-kel', 'loser / dope', 'one who trudges', 'The Netherlands'' default mild insult. Almost cosy.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-02', 'nl', 'oen', 'oon', 'dope', 'possibly from ''hoen'' (fowl)', 'Three letters of pure Dutch efficiency.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-03', 'nl', 'mafkees', 'MAF-case', 'weirdo', 'crazy Kees (a first name)', 'Poor Kees — the Dutch Miesepeter. A whole name sacrificed.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-04', 'nl', 'droeftoeter', 'DROOF-too-ter', 'sad sack', 'sad horn', 'A horn that plays only sad notes. Devastating and adorable.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-05', 'nl', 'kletskous', 'KLETS-kows', 'chatterbox', 'chatter-stocking', 'Why a stocking? Unclear. The Dutch have moved on; so should you.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-06', 'nl', 'luiwammes', 'LOWY-wham-mes', 'lazybones', 'lazy jacket', 'A garment so lazy it became a person.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-07', 'nl', 'zeikerd', 'ZAY-kert', 'whiner', 'pisser', 'From ''zeiken'' (to piss / to nag). For professional complainers.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-08', 'nl', 'eikel', 'EYE-kel', 'jerk', 'acorn / glans', 'Botanically an acorn, anatomically not. Handle with a grin.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-09', 'nl', 'rot op', 'rot OP', 'get lost', 'rot away', 'Direct, like most things Dutch.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('nl-10', 'nl', 'klootzak', 'KLOHT-zak', 'asshole', 'ball sack', 'The serious one. Famous enough that foreigners learn it first — don''t lead with it.', 'nuclear', 3);
insert into languages (code, name, native_name, flag, status, note) values ('ja', 'Japanese', '日本語', '🇯🇵', 'starter', null);
insert into variants (code, language_code, name, flag) values ('ja-JP', 'ja', 'Japanese', '🇯🇵');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-01', 'ja', 'ばか', 'baka (BAH-kah)', 'idiot', 'possibly ''horse-deer'' (馬鹿)', 'The world''s most famous Japanese insult. Mild in Tokyo, harsher in Osaka.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-02', 'ja', 'あほ', 'aho (AH-hoh)', 'fool', 'fool', 'The Kansai counterpart: affectionate in Osaka, ruder in Tokyo. Exact mirror of baka.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-03', 'ja', 'まぬけ', 'manuke (mah-NOO-keh)', 'dimwit', 'missing a beat (間抜け)', 'From music/theatre: someone whose timing in life is simply off.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-04', 'ja', 'ぼけ', 'boke (BOH-keh)', 'space cadet', 'blurred / fuzzy', 'Also the ''funny man'' role in manzai comedy duos — the airhead half.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-05', 'ja', 'くそ', 'kuso (koo-soh)', 'damn / crap', 'excrement', 'The all-purpose gamer grunt. Attach to anything: kuso-game = bad game.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-06', 'ja', 'だまれ', 'damare (dah-mah-reh)', 'shut up', 'be silent (imperative)', 'Anime taught the world this one. Rude in real offices.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-07', 'ja', 'へたくそ', 'hetakuso (heh-tah-koo-soh)', 'terrible at it', 'unskilled + crap', 'The standard judgement of someone''s parking, gaming, or karaoke.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-08', 'ja', 'けち', 'kechi (KEH-chee)', 'cheapskate', 'stingy', 'For the colleague who calculates their share of lunch to the yen.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-09', 'ja', 'なまけもの', 'namakemono (nah-mah-keh-moh-noh)', 'lazybones', 'lazy thing', 'Also the Japanese word for ''sloth'' (the animal). Nature agrees.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ja-10', 'ja', 'うざい', 'uzai (oo-zye)', 'annoying', 'from uzattai', 'Teen slang staple. One word, maximum eye-roll.', 'banter', 1);
insert into languages (code, name, native_name, flag, status, note) values ('pt', 'Portuguese', 'Português', '🇵🇹', 'starter', null);
