insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-01', 'pt', 'parvo', 'PAR-voo', 'fool', 'small / foolish', 'Portugal''s everyday fool; mild enough for the dinner table.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('pt-01', 'pt-PT');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-02', 'pt', 'palerma', 'pah-LAIR-mah', 'dimwit', 'dimwit', 'Classic Portuguese; often paired with a slow, sad head-shake.', 'banter', 1);
insert into entry_variants (entry_id, variant_code) values ('pt-02', 'pt-PT');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-03', 'pt', 'chato', 'SHAH-too', 'annoying', 'flat', 'Both countries agree: a chato flattens the mood of any room.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-04', 'pt', 'vai à fava', 'vy ah FAH-vah', 'get lost', 'go to the fava bean', 'Historic: voting was once done with fava beans. Now it means ''shoo''.', 'playful', 1);
insert into entry_variants (entry_id, variant_code) values ('pt-04', 'pt-PT');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-05', 'pt', 'otário', 'oh-TAH-ree-oo', 'sucker', 'sucker', 'Brazil''s word for someone who falls for everything.', 'banter', 2);
insert into entry_variants (entry_id, variant_code) values ('pt-05', 'pt-BR');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-06', 'pt', 'babaca', 'bah-BAH-kah', 'jerk', 'fool', 'Everyday Brazilian; the standard rating for bad drivers.', 'frustration', 2);
insert into entry_variants (entry_id, variant_code) values ('pt-06', 'pt-BR');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-07', 'pt', 'merda', 'MAIR-dah', 'shit', 'shit', 'Universal Portuguese; also ''muita merda!'' means ''break a leg'' in theatre.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-08', 'pt', 'porra', 'POH-hah', 'damn', 'vulgar: semen / old word for club', 'Brazil''s comma. Punctuates surprise, anger, and football matches.', 'frustration', 3);
insert into entry_variants (entry_id, variant_code) values ('pt-08', 'pt-BR');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-09', 'pt', 'caralho', 'kah-RAH-lyoo', 'damn / fuck', 'vulgar: penis; also a ship''s crow''s nest', 'Legend says sailors were sent ''to the caralho'' (crow''s nest) as punishment.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('pt-10', 'pt', 'filho da puta', 'FEE-lyoo dah POO-tah', 'son of a bitch', 'son of a whore', 'Maximum strength in both countries. Not for karaoke night.', 'nuclear', 3);
insert into languages (code, name, native_name, flag, status, note) values ('ru', 'Russian', 'Русский', '🇷🇺', 'starter', null);
insert into variants (code, language_code, name, flag) values ('ru-RU', 'ru', 'Russian', '🇷🇺');
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-01', 'ru', 'дурак', 'durák (doo-RAHK)', 'fool', 'fool', 'The folk-tale classic — Ivan the Fool is Russia''s favourite hero. Mild.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-02', 'ru', 'балбес', 'balbés (bal-BYES)', 'goofball', 'dolt', 'Affectionate; the name of a beloved Soviet comedy character.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-03', 'ru', 'болван', 'bolván (bal-VAHN)', 'blockhead', 'wooden idol / dummy', 'Originally a carved idol or hat-block: solid wood, all the way through.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-04', 'ru', 'лентяй', 'lentyáy (len-TYAY)', 'lazybones', 'lazy one', 'What every Russian grandmother calls every Russian grandchild.', 'playful', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-05', 'ru', 'зануда', 'zanúda (za-NOO-dah)', 'bore / nag', 'one who drones', 'The person who explains the movie during the movie.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-06', 'ru', 'придурок', 'pridúrok (pree-DOO-rok)', 'halfwit', 'near-fool', 'The prefix ''pri-'' means ''somewhat'' — mathematically, 0.7 of a durak.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-07', 'ru', 'идиот', 'idiót (ee-dee-OHT)', 'idiot', 'idiot', 'Elevated by Dostoevsky to literature; still lands hard in traffic.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-08', 'ru', 'козёл', 'kozyól (ka-ZYOL)', 'jerk', 'male goat', 'Far heavier than ''goat'' suggests — serious criminal-slang baggage. Never say it lightly to a Russian man.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-09', 'ru', 'сволочь', 'svóloch (SVOH-loch)', 'scum', 'things dragged together / debris', 'Originally rubbish swept into a pile. Strong, theatrical, very Chekhov-when-angry.', 'nuclear', 3);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('ru-10', 'ru', 'мудак', 'mudák (moo-DAHK)', 'asshole', 'vulgar (from testicle)', 'Firmly in mat (obscene register) territory. The real deal — not for the office.', 'nuclear', 3);
insert into languages (code, name, native_name, flag, status, note) values ('tr', 'Turkish', 'Türkçe', '🇹🇷', 'starter', null);
