insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-01', 'tr', 'aptal', 'ap-TAHL', 'idiot', 'idiot', 'The everyday baseline; safe among friends.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-02', 'tr', 'salak', 'sah-LAHK', 'fool', 'fool', 'Aptal''s twin; Turks debate which is worse. Neither, really.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-03', 'tr', 'gerizekalı', 'geh-ree-zeh-kah-LUH', 'moron', 'backward-minded', 'Longer word, stronger sting.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-04', 'tr', 'mal', 'mahl', 'dimwit', 'goods / livestock', 'Being called merchandise: brutally efficient Turkish economy of words.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-05', 'tr', 'öküz', 'er-KUUZ', 'oaf', 'ox', 'For clumsy, graceless behaviour. The ox files a complaint.', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-06', 'tr', 'hıyar', 'huh-YAR', 'jerk', 'cucumber', 'Turkey insults you with salad ingredients. See also: kabak (zucchini).', 'banter', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-07', 'tr', 'dangalak', 'dahn-gah-LAHK', 'blockhead', 'blockhead', 'Wonderfully percussive to shout. Try it: dan-ga-lak.', 'frustration', 2);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-08', 'tr', 'beyinsiz', 'beh-yeen-SEEZ', 'brainless', 'without brain', 'The suffix -siz (without) makes Turkish insults modular. Attach to anything.', 'banter', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-09', 'tr', 'hadi oradan', 'HAH-dee oh-rah-DAHN', 'get out of here', 'come on, from there', 'Disbelief and dismissal in one gesture-heavy package.', 'frustration', 1);
insert into entries (id, language_code, original, phonetic, translation, literal, note, category_id, severity) values ('tr-10', 'tr', 'kıl', 'kuhl', 'irritating', 'body hair', '''Kıl herif'' = an irritating guy. Precisely as itchy as it sounds.', 'banter', 1);
